def transform(grid):
    """Mirror-tile a square grid in a 3x3 arrangement."""
    n = len(grid)
    if n == 0:
        return []

    out = []
    for tile_row in range(3):
        flip_vertical = tile_row == 0 or tile_row == 2
        for source_row in range(n):
            row_index = n - 1 - source_row if flip_vertical else source_row
            row = []
            for tile_col in range(3):
                flip_horizontal = tile_col == 0 or tile_col == 2
                for source_col in range(n):
                    col_index = n - 1 - source_col if flip_horizontal else source_col
                    row.append(grid[row_index][col_index])
            out.append(row)
    return out
